<?php use SPFPU\Core\{Auth,Csrf,View}; ?>
<header class="page-head"><div><p class="eyebrow">Ruang kerja rekod</p><h1>Kategori</h1><p>Mulakan dengan kategori untuk melihat fail dan jilid persuratan.</p></div><?php if($user['role']==='Admin'):?><button class="button primary" data-dialog-open="kategori-baru">Tambah kategori</button><?php endif?></header>
<section class="record-list" aria-label="Senarai kategori">
<?php if(!$categories):?><div class="empty"><span>01</span><h2>Belum ada kategori</h2><p>Admin boleh mewujudkan kategori pertama untuk memulakan struktur rekod.</p></div><?php endif?>
<?php foreach($categories as $i=>$category):?><a class="record-row" href="/kategori/<?=(int)$category['id']?>"><span class="row-index"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><span class="row-main"><strong><?=View::e($category['name'])?></strong><small><?=View::e($category['description']?:'Tiada keterangan')?></small></span><span class="row-metric"><b><?=(int)$category['folder_count']?></b> Fail</span><span class="row-metric"><b><?=(int)$category['entry_count']?></b> Entri</span><span class="row-arrow" aria-hidden="true">↗</span></a><?php endforeach?>
</section>
<?php if($user['role']==='Admin'):?><dialog id="kategori-baru"><form method="post" action="/kategori" class="dialog-form"><?=Csrf::field()?><header><div><p class="eyebrow">Struktur baharu</p><h2>Tambah kategori</h2></div><button type="button" class="icon-button" data-dialog-close aria-label="Tutup">×</button></header><label>Nama Kategori<input name="name" maxlength="150" required></label><label>Keterangan <span>(pilihan)</span><textarea name="description" maxlength="500" rows="3"></textarea></label><footer><button type="button" class="button quiet" data-dialog-close>Batal</button><button class="button primary">Simpan kategori</button></footer></form></dialog><?php endif?>
